/**
 * Korean conjugation-trainer provider (Phase 1).
 *
 * Implements the generic `ConjugationTrainerProvider` so the shared drill
 * surface lights up for KO exactly as it does for JA — driven by
 * `getLanguageModule("ko").conjugation.trainer`, with zero KO-specific code in
 * the UI. Forms + distractors are generated by the jamo engine
 * (`conjugationEngine.ts`) off the authored lemma list (`conjugationTables.ts`).
 *
 * Phase 1 scope (per docs/ja-ko-parity-audit-2026-07-15.md §2.5):
 *   - drills gate on REACHED MODULE only;
 *   - NO Track-B grammar SRS integration (grading is a no-op — see the TODO in
 *     `gradeSessionIfOnPath`). Phase 2 generalizes `grammarSrs.ts` off the JA
 *     atom map and wires a `ko-grammar-points.json`;
 *   - NO combo (stacked) forms and NO free drill yet — the hub degrades to
 *     free-mix multi-select and hides the Mix tile.
 */
import type {
  ConjugationTrainerProvider,
  ConjTrainerTypeMeta,
  ConjTrainerQuestion,
  ConjWordClassInfo,
  ConjCheatItem,
  ConjFormationRow,
  ConjExampleSentence,
} from "@/shared/conjugation/types";
import { shuffle, clamp, roundRobinBuild, type QuestionFactory } from "@/shared/conjugation/session";
import { registerConjugationTrainer } from "@/shared/conjugation/registry";
import {
  conjugateKo,
  generateKoDistractors,
  type KoFormKey,
  type KoStemClass,
} from "./conjugationEngine";
import { KO_LEMMAS, getLemmasUpToModule, type KoLemma } from "./conjugationTables";

// ─── Trainer types (hub tiles) ────────────────────────────────────────────

interface KoTile {
  id: string;
  title: string;
  subtitle: string;
  glyph: string;
  colorVar: string;
  form: KoFormKey;
  unlockModule: number;
  verbsOnly: boolean;
  category: "verb" | "adjective";
  formation: ConjFormationRow[];
}

const R = (groupLabel: string, pattern: string, exampleDict: string, exampleForm: string): ConjFormationRow => ({
  groupLabel,
  pattern,
  exampleDict,
  exampleForm,
});

