// ─── Session building ─────────────────────────────────────────────────────

function poolFor(tile: KoTile, poolModule: number): KoLemma[] {
  const pool = getLemmasUpToModule(poolModule);
  return tile.verbsOnly ? pool.filter((l) => l.pos === "verb") : pool;
}

/** Build one MCQ; pads to 4 options with other lemmas' same-form values when
 *  the rule-misapplication generator returns fewer than 3 distractors. */
function makeQuestion(lemma: KoLemma, form: KoFormKey, pool: KoLemma[]): ConjTrainerQuestion {
  const correct = conjugateKo(lemma.lemma, lemma.cls, form);
  const distractors = generateKoDistractors(lemma.lemma, lemma.cls, form, correct);
  if (distractors.length < 3) {
    const seen = new Set<string>([correct, ...distractors]);
    for (const other of shuffle(pool)) {
      if (other.id === lemma.id) continue;
      const alt = conjugateKo(other.lemma, other.cls, form);
      if (!seen.has(alt)) {
        seen.add(alt);
        distractors.push(alt);
      }
      if (distractors.length >= 3) break;
    }
  }
  return {
    itemId: `${lemma.id}:${form}`,
    prompt: lemma.lemma,
    meaning: lemma.meaning,
    wordClassId: lemma.cls,
    formLabel: FORM_LABELS[form] ?? form,
    form,
    correct,
    options: shuffle([correct, ...distractors.slice(0, 3)]),
    isAdjective: lemma.pos === "adjective",
    example: koQuestionExample(lemma.meaning, form, lemma.pos === "adjective", correct),
  };
}

const MIN_Q = 6;
const MAX_Q = 12;

function toMeta(tile: KoTile): ConjTrainerTypeMeta {
  return {
    id: tile.id,
    title: tile.title,
    subtitle: tile.subtitle,
    category: tile.category,
    group: TILE_GROUP[tile.id],
    // Non-verb-only forms include descriptive verbs (adjectives) in their pool.
    adjective: !tile.verbsOnly,
    example: TILE_EXAMPLE[tile.id],
    glyph: tile.glyph,
    colorVar: tile.colorVar,
    unlockModule: tile.unlockModule,
    formation: tile.formation,
  };
}

function unlockModuleFor(id: string): number {
  return TILE_BY_ID.get(id)?.unlockModule ?? 0;
}

// ─── Scoped CSS (KO palette + shared drill-card ink styles) ───────────────

const KO_SCOPE_CSS = `
.conj-scope {
  --type-haeyo:#047857; --type-banmal:#7c3aed; --type-formal:#1d4ed8;
  --type-past:#b45309; --type-future:#0e7490; --type-prog:#be185d; --type-neg:#b91c1c;
  --type-want:#c2410c; --type-and:#0f766e; --type-cmd:#4338ca; --type-adv:#a16207;
  --type-but:#9f1239; --type-so:#15803d; --type-if:#6d28d9; --type-proh:#be123c;
  --type-plain:#0369a1;
  --type-default:#6b7280;
}
.dark .conj-scope {
  --type-haeyo:#34d399; --type-banmal:#c084fc; --type-formal:#60a5fa;
  --type-past:#fbbf24; --type-future:#22d3ee; --type-prog:#f472b6; --type-neg:#f87171;
  --type-want:#fb923c; --type-and:#2dd4bf; --type-cmd:#818cf8; --type-adv:#facc15;
  --type-but:#fb7185; --type-so:#4ade80; --type-if:#a78bfa; --type-proh:#fda4af;
  --type-plain:#38bdf8;
  --type-default:#9ca3af;
}
.conj-tile-suggest { animation: conj-wobble 4s ease-in-out infinite; }
@keyframes conj-wobble { 2% { transform: rotate(1.1deg); } 4% { transform: rotate(-1.1deg); } 6% { transform: rotate(0); } }
.conj-scope .conj-opt { position: relative; overflow: hidden; }
.conj-scope .conj-opt::before {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 0;
  background: color-mix(in srgb, var(--fc, rgb(var(--color-accent))) 12%, transparent);
  transition: height 0.16s ease;
}
.conj-scope .conj-opt > * { position: relative; }
.conj-scope .conj-opt:not(:disabled):hover { border-color: var(--fc, rgb(var(--color-accent))); }
.conj-scope .conj-opt:not(:disabled):hover::before { height: 100%; }
.conj-scope .conj-opt-correct { animation: conj-pop 0.3s ease; }
.conj-scope .conj-opt-wrong { animation: conj-shake 0.3s ease; }
.conj-scope .conj-cheat-nudge { animation: conj-shake 0.35s ease, conj-wobble 5s ease-in-out 1s infinite; }
@keyframes conj-pop { 35% { transform: scale(1.04); } 100% { transform: scale(1); } }
@keyframes conj-shake { 20% { transform: translateX(-4px); } 45% { transform: translateX(4px); } 70% { transform: translateX(-2px); } 100% { transform: translateX(0); } }
@media (prefers-reduced-motion: reduce) {
  .conj-tile-suggest, .conj-scope .conj-opt-correct, .conj-scope .conj-opt-wrong, .conj-scope .conj-cheat-nudge { animation: none; }
  .conj-scope .conj-opt::before { transition: none; }
}
`.trim();

// ─── Provider ─────────────────────────────────────────────────────────────

export const koConjugationTrainer: ConjugationTrainerProvider = {
  tileOrder: TILE_ORDER,
  getTypes: () => KO_TILES.map(toMeta),
  getType: (id) => {
    const t = TILE_BY_ID.get(id);
    return t ? toMeta(t) : undefined;
  },

  scopeCss: KO_SCOPE_CSS,
  glyph: (id) => TILE_BY_ID.get(id)?.glyph ?? "",
  // Fallback resolves to a standalone-hex `--type-*` var so `var(${colorVar})`
  // stays a valid color (post-W1 `--color-accent` is a bare channel triple).
  colorVar: (id) => TILE_BY_ID.get(id)?.colorVar ?? "--type-default",
  mixGlyphs: KO_TILES.slice(0, 5).map((t) => ({ glyph: t.glyph, colorVar: t.colorVar })),

  wordClass: (id) =>
    WORD_CLASS[id as KoStemClass] ?? {
      labelKey: `practice.conjugation.koClass${id}`,
      labelDefault: id,
      explainKey: `practice.conjugation.koClass${id}Explain`,
      explainDefault: "",
      irregular: false,
    },

  // KO has no second script (Hangul is phonetic) — always plain.
  secondScriptExposureModule: undefined,
  renderSurface: (_question, surface) => [{ text: surface }],

  isTypeUnlocked: (id, reachedModule) => reachedModule >= unlockModuleFor(id),
  isSelectionAhead: (ids, reachedModule) =>
    ids.some((id) => reachedModule < unlockModuleFor(id)),
  effectivePoolModule: (ids, reachedModule) =>
    Math.max(reachedModule, ...ids.map((id) => unlockModuleFor(id)), 0),

  // Combos not authored for KO in Phase 1 — the hub degrades to free-mix.
  supportsCombos: false,
  combosForSelection: () => [],
  canExtendSelection: () => true,
  missingComboTiles: () => null,
  formToTiles: (form) => {
    const tile = KO_TILES.find((t) => t.form === form);
    return tile ? [tile.id] : undefined;
  },
  individualFormCount: (ids) => new Set(ids).size,

  buildSession: (typeId, poolModule) => {
    const tile = TILE_BY_ID.get(typeId);
    if (!tile) return [];
    const pool = poolFor(tile, poolModule);
    if (pool.length === 0) return [];
    const target = clamp(pool.length, MIN_Q, MAX_Q);
    const shuffled = shuffle(pool);
    return Array.from({ length: target }, (_, i) =>
      makeQuestion(shuffled[i % shuffled.length], tile.form, pool),
    );
  },
  buildCombinedSession: (typeIds, poolModule) => {
    const tiles = typeIds
      .map((id) => TILE_BY_ID.get(id))
      .filter((t): t is KoTile => !!t);
    if (tiles.length === 0) return [];
    const factories: QuestionFactory<ConjTrainerQuestion>[] = tiles.map((tile) => {
      const pool = poolFor(tile, poolModule);
      return {
        form: tile.form,
        pool,
        make: (item) => makeQuestion(item as KoLemma, tile.form, pool),
      };
    });
    const target = clamp(12, 8, 14);
    return roundRobinBuild(factories, target);
  },

  // Phase 1: no Track-B SRS for KO. Mastery/due are neutral.
  typeMasteryPercent: () => 0,
  dueCount: () => 0,

  // TODO(Phase 2): wire KO Track-B grammar SRS (generalize grammarSrs.ts off
  // JA_COURSE_ATOMS + add ko-grammar-points.json). Until then KO drills are
  // reached-module gated and write no review schedule.
  gradeSessionIfOnPath: (typeId, reachedModule) =>
    reachedModule >= unlockModuleFor(typeId),
  gradeCombinedSessionIfOnPath: (typeIds, reachedModule) =>
    !typeIds.some((id) => reachedModule < unlockModuleFor(id)),

  cheatItems: (typeId, reachedModule): ConjCheatItem[] => {
    const tile = TILE_BY_ID.get(typeId);
    if (!tile) return [];
    return poolFor(tile, reachedModule)
      .slice(0, 8)
      .map((l) => ({ dict: l.lemma, form: conjugateKo(l.lemma, l.cls, tile.form) }));
  },

  getIntroStep: () => null,

  // freeDrill omitted — Mix tile hidden for KO in Phase 1.
};

export { KO_LEMMAS };

registerConjugationTrainer("ko", koConjugationTrainer);
